import { useEffect, useMemo, useState } from "react";
import { format } from "date-fns";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { BookOpenCheck, CalendarDays, CheckCircle2, FileText, Loader2, Plus, ShieldCheck, Users } from "lucide-react";

const today = new Date().toISOString().slice(0, 10);
const kes = new Intl.NumberFormat("en-KE", { style: "currency", currency: "KES", maximumFractionDigits: 0 });

function formatKes(value: number | string | null | undefined) {
  return kes.format(Number(value ?? 0));
}

function formatDate(value: Date | string | null | undefined) {
  return value ? format(new Date(value), "d MMM yyyy") : "—";
}

function WorkflowCard({ title, copy, children }: { title: string; copy: string; children: React.ReactNode }) {
  return <Card className="border-emerald-950/8 bg-white/85 dark:border-white/8 dark:bg-[#172420]"><CardHeader className="pb-3"><CardTitle className="text-base text-[#143b31] dark:text-emerald-50">{title}</CardTitle><CardDescription className="leading-5">{copy}</CardDescription></CardHeader><CardContent>{children}</CardContent></Card>;
}

function StudentSelect({ students, value, onChange }: { students: Array<{ id: number; firstName: string; lastName: string; admissionNo: string }>; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select learner" /></SelectTrigger><SelectContent>{students.map(student => <SelectItem key={student.id} value={String(student.id)}>{student.firstName} {student.lastName} · {student.admissionNo}</SelectItem>)}</SelectContent></Select>;
}

function TeacherSelect({ teachers, value, onChange }: { teachers: Array<{ id: number; firstName: string; lastName: string; employeeNo: string }>; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select teacher" /></SelectTrigger><SelectContent>{teachers.map(teacher => <SelectItem key={teacher.id} value={String(teacher.id)}>{teacher.firstName} {teacher.lastName} · {teacher.employeeNo}</SelectItem>)}</SelectContent></Select>;
}

function SubjectSelect({ subjects, value, onChange }: { subjects: Array<{ id: number; name: string; code: string }>; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select subject" /></SelectTrigger><SelectContent>{subjects.map(subject => <SelectItem key={subject.id} value={String(subject.id)}>{subject.name} · {subject.code}</SelectItem>)}</SelectContent></Select>;
}

function ClassSelect({ classes, value, onChange }: { classes: Array<{ id: number; form: string; stream: string }>; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select class" /></SelectTrigger><SelectContent>{classes.map(schoolClass => <SelectItem key={schoolClass.id} value={String(schoolClass.id)}>{schoolClass.form} · {schoolClass.stream}</SelectItem>)}</SelectContent></Select>;
}

function YearSelect({ years, value, onChange }: { years: Array<{ id: number; name: string }>; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Academic year" /></SelectTrigger><SelectContent>{years.map(year => <SelectItem key={year.id} value={String(year.id)}>{year.name}</SelectItem>)}</SelectContent></Select>;
}

function TermSelect({ terms, yearId, value, onChange }: { terms: Array<{ id: number; name: string; academicYearId: number }>; yearId: string; value: string; onChange: (value: string) => void }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Term" /></SelectTrigger><SelectContent>{terms.filter(term => !yearId || term.academicYearId === Number(yearId)).map(term => <SelectItem key={term.id} value={String(term.id)}>{term.name}</SelectItem>)}</SelectContent></Select>;
}

export function StudentLifecycleEntry() {
  const students = trpc.school.students.list.useQuery({ status: "active" });
  const [statusForm, setStatusForm] = useState({ studentId: "", status: "active" as "active" | "transferred" | "completed" | "inactive" });
  const [documentForm, setDocumentForm] = useState({ studentId: "", documentType: "Birth certificate", file: null as File | null });
  const [fileKey, setFileKey] = useState(0);
  const statusUpdate = trpc.school.students.updateStatus.useMutation({ onSuccess: () => { toast.success("Student status updated. Ready for the next record."); setStatusForm({ studentId: "", status: "active" }); students.refetch(); }, onError: error => toast.error(error.message) });
  const upload = trpc.school.students.uploadDocument.useMutation({ onSuccess: () => { toast.success("Document stored securely. Ready for the next upload."); setDocumentForm({ studentId: "", documentType: "Birth certificate", file: null }); setFileKey(current => current + 1); }, onError: error => toast.error(error.message) });
  const uploadDocument = () => {
    if (!documentForm.file || !documentForm.studentId) return toast.error("Choose a learner and a PDF or image document.");
    const reader = new FileReader();
    reader.onload = () => upload.mutate({ studentId: Number(documentForm.studentId), fileName: documentForm.file!.name, mimeType: documentForm.file!.type as "application/pdf" | "image/jpeg" | "image/png", documentType: documentForm.documentType, base64: String(reader.result) });
    reader.readAsDataURL(documentForm.file);
  };
  return <div className="mb-6 grid gap-5 xl:grid-cols-2"><WorkflowCard title="Learner status" copy="Update a learner’s lifecycle while retaining the academic history and audit trail."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (!statusForm.studentId) return toast.error("Select a learner."); statusUpdate.mutate({ studentId: Number(statusForm.studentId), status: statusForm.status }); }}><StudentSelect students={students.data ?? []} value={statusForm.studentId} onChange={value => setStatusForm({ ...statusForm, studentId: value })} /><Select value={statusForm.status} onValueChange={value => setStatusForm({ ...statusForm, status: value as typeof statusForm.status })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent>{["active", "transferred", "completed", "inactive"].map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={statusUpdate.isPending}>{statusUpdate.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}Update learner status</Button></form></WorkflowCard><WorkflowCard title="Secure learner documents" copy="PDF, JPEG and PNG files are stored in protected object storage; only a durable reference is kept in the database."><div className="grid gap-3 sm:grid-cols-2"><StudentSelect students={students.data ?? []} value={documentForm.studentId} onChange={value => setDocumentForm({ ...documentForm, studentId: value })} /><Input value={documentForm.documentType} onChange={event => setDocumentForm({ ...documentForm, documentType: event.target.value })} placeholder="Document type" className="rounded-xl" /><Input key={fileKey} type="file" accept="application/pdf,image/jpeg,image/png" className="rounded-xl sm:col-span-2" onChange={event => setDocumentForm({ ...documentForm, file: event.target.files?.[0] ?? null })} /><Button type="button" className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={upload.isPending} onClick={uploadDocument}>{upload.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <FileText className="mr-2 h-4 w-4" />}Store document securely</Button></div></WorkflowCard></div>;
}

export function AccountStatusEntry({ accountType }: { accountType: "student" | "teacher" }) {
  const students = trpc.school.students.list.useQuery({ status: "active" });
  const teachers = trpc.school.teachers.list.useQuery();
  const [accountId, setAccountId] = useState("");
  const [reason, setReason] = useState("");
  const setStatus = trpc.school.accountStatus.set.useMutation({ onSuccess: result => { toast.success(result.disabled ? "Account temporarily disabled." : "Account re-enabled."); setAccountId(""); setReason(""); void students.refetch(); void teachers.refetch(); }, onError: error => toast.error(error.message) });
  const rows = accountType === "student" ? students.data ?? [] : teachers.data ?? [];
  const selected = rows.find(row => row.id === Number(accountId));
  const disabled = Boolean(selected?.disabledAt);
  const label = accountType === "student" ? "learner" : "teacher";
  return <WorkflowCard title={`Temporarily disable a ${label} account`} copy={`Pause ${label} sign-in without deleting records. The action is school-scoped, audited, and can be reversed by authorised school leadership.`}><div className="grid gap-3 sm:grid-cols-2"><div>{accountType === "student" ? <StudentSelect students={students.data ?? []} value={accountId} onChange={setAccountId} /> : <TeacherSelect teachers={teachers.data ?? []} value={accountId} onChange={setAccountId} />} {selected ? <div className={`mt-2 rounded-xl px-3 py-2 text-xs ${disabled ? "bg-rose-50 text-rose-700 dark:bg-rose-950/30 dark:text-rose-300" : "bg-[#e8f1ec] text-[#0d4437] dark:bg-emerald-950/30 dark:text-emerald-300"}`}><span className="font-semibold">{disabled ? "Temporarily disabled" : "Active for login"}</span>{disabled && selected.disabledReason ? <span className="ml-1">· {selected.disabledReason}</span> : null}</div> : null}</div><Input value={reason} onChange={event => setReason(event.target.value)} placeholder={disabled ? "Optional note for re-enable" : "Reason for temporary disable"} maxLength={255} className="rounded-xl" /><Button type="button" className={cn("rounded-xl text-white sm:col-span-2", disabled ? "bg-[#0d4437] hover:bg-[#092f26]" : "bg-rose-700 hover:bg-rose-800")} disabled={!accountId || setStatus.isPending} onClick={() => setStatus.mutate({ accountType, accountId: Number(accountId), disabled: !disabled, reason: reason.trim() || undefined })}>{setStatus.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <ShieldCheck className="mr-2 h-4 w-4" />}{disabled ? `Re-enable ${label} login` : `Temporarily disable ${label} login`}</Button></div></WorkflowCard>;
}

export function StudentSubjectEntry() {
  const students = trpc.school.students.list.useQuery({ status: "active" });
  const config = trpc.school.academics.config.useQuery();
  const [studentId, setStudentId] = useState("");
  const [subjectIds, setSubjectIds] = useState<number[]>([]);
  const setSubjects = trpc.school.students.setSubjects.useMutation({ onSuccess: () => { toast.success("Subject allocation saved. Ready for the next learner."); setStudentId(""); setSubjectIds([]); }, onError: error => toast.error(error.message) });
  const subjects = config.data?.subjects ?? [];
  return <WorkflowCard title="Learner subject allocation" copy="Assign the subjects a learner is currently taking after admission. The school and role are checked by the server before saving."><form onSubmit={event => { event.preventDefault(); if (!studentId) return toast.error("Select a learner."); setSubjects.mutate({ studentId: Number(studentId), subjectIds }); }}><StudentSelect students={students.data ?? []} value={studentId} onChange={setStudentId} /><div className="mt-4 grid gap-2 sm:grid-cols-2">{subjects.map(subject => <label key={subject.id} className="flex items-center gap-2 rounded-xl border border-emerald-950/8 p-2.5 text-sm dark:border-white/8"><input type="checkbox" checked={subjectIds.includes(subject.id)} onChange={() => setSubjectIds(current => current.includes(subject.id) ? current.filter(id => id !== subject.id) : [...current, subject.id])} className="h-4 w-4 accent-[#0d4437]" /><span>{subject.name}</span><span className="ml-auto font-mono text-xs text-slate-400">{subject.code}</span></label>)}</div><Button type="submit" className="mt-4 rounded-xl bg-[#0d4437] text-white" disabled={setSubjects.isPending}>{setSubjects.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Users className="mr-2 h-4 w-4" />}Save subject allocation</Button></form></WorkflowCard>;
}

export function TeacherWorkflowEntry() {
  const config = trpc.school.academics.config.useQuery();
  const teachers = trpc.school.teachers.list.useQuery();
  const [teacher, setTeacher] = useState({ employeeNo: "", firstName: "", lastName: "", departmentId: "" });
  const [allocation, setAllocation] = useState({ teacherId: "", subjectId: "", classId: "", yearId: "", termId: "" });
  const [attendance, setAttendance] = useState({ teacherId: "", status: "present" as "present" | "absent" | "late" | "on_leave" });
  const [staffDepartmentId, setStaffDepartmentId] = useState("");
  const [edit, setEdit] = useState({ id: "", employeeNo: "", firstName: "", lastName: "", phone: "", email: "", employmentStatus: "active" as "active" | "on_leave" | "inactive" });
  const create = trpc.school.teachers.create.useMutation({ onSuccess: () => { toast.success("Teacher profile created. Add the next teacher when ready."); setTeacher({ employeeNo: "", firstName: "", lastName: "", departmentId: "" }); teachers.refetch(); }, onError: error => toast.error(error.message) });
  const assign = trpc.school.academics.assignTeacher.useMutation({ onSuccess: () => { toast.success("Teaching allocation saved. Ready for the next allocation."); setAllocation({ teacherId: "", subjectId: "", classId: "", yearId: "", termId: "" }); }, onError: error => toast.error(error.message) });
  const setDepartment = trpc.school.teachers.setDepartment.useMutation({ onSuccess: () => { toast.success("Teacher department saved. Ready for the next update."); setAttendance(current => ({ ...current, teacherId: "" })); setStaffDepartmentId(""); teachers.refetch(); }, onError: error => toast.error(error.message) });
  const recordAttendance = trpc.school.teachers.recordAttendance.useMutation({ onSuccess: () => { toast.success("Teacher attendance saved. Ready for the next staff member."); setAttendance({ teacherId: "", status: "present" }); }, onError: error => toast.error(error.message) });
  const update = trpc.school.teachers.update.useMutation({ onSuccess: () => { toast.success("Teacher profile updated."); setEdit({ id: "", employeeNo: "", firstName: "", lastName: "", phone: "", email: "", employmentStatus: "active" }); teachers.refetch(); }, onError: error => toast.error(error.message) });
  const remove = trpc.school.teachers.remove.useMutation({ onSuccess: () => { toast.success("Teacher removed."); setEdit({ id: "", employeeNo: "", firstName: "", lastName: "", phone: "", email: "", employmentStatus: "active" }); teachers.refetch(); }, onError: error => toast.error(error.message) });
  const teacherRows = teachers.data ?? [];
  const classes = config.data?.classes ?? [];
  const subjects = config.data?.subjects ?? [];
  const years = config.data?.academicYears ?? [];
  const terms = config.data?.terms ?? [];
  const departments = config.data?.departments ?? [];
  return <div className="mb-6 grid gap-5 xl:grid-cols-2"><WorkflowCard title="Teacher profile" copy="Create a teaching profile and place it in a department. Successful saves clear the form for the next profile."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); create.mutate({ employeeNo: teacher.employeeNo, firstName: teacher.firstName, lastName: teacher.lastName, departmentId: teacher.departmentId ? Number(teacher.departmentId) : undefined }); }}><Input value={teacher.employeeNo} onChange={event => setTeacher({ ...teacher, employeeNo: event.target.value })} placeholder="Employee number" className="rounded-xl" required /><Input value={teacher.firstName} onChange={event => setTeacher({ ...teacher, firstName: event.target.value })} placeholder="First name" className="rounded-xl" required /><Input value={teacher.lastName} onChange={event => setTeacher({ ...teacher, lastName: event.target.value })} placeholder="Last name" className="rounded-xl" required /><Select value={teacher.departmentId} onValueChange={value => setTeacher({ ...teacher, departmentId: value })}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Department (optional)" /></SelectTrigger><SelectContent>{departments.map(department => <SelectItem key={department.id} value={String(department.id)}>{department.name}</SelectItem>)}</SelectContent></Select><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={create.isPending}>{create.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Plus className="mr-2 h-4 w-4" />}Create teacher profile</Button></form></WorkflowCard><WorkflowCard title="Teaching allocation" copy="Assign a teacher to a subject and class for the academic year before marks entry is allowed."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (![allocation.teacherId, allocation.subjectId, allocation.classId, allocation.yearId].every(Boolean)) return toast.error("Complete all required allocation fields."); assign.mutate({ teacherId: Number(allocation.teacherId), subjectId: Number(allocation.subjectId), classId: Number(allocation.classId), academicYearId: Number(allocation.yearId), termId: allocation.termId ? Number(allocation.termId) : undefined }); }}><TeacherSelect teachers={teacherRows} value={allocation.teacherId} onChange={value => setAllocation({ ...allocation, teacherId: value })} /><SubjectSelect subjects={subjects} value={allocation.subjectId} onChange={value => setAllocation({ ...allocation, subjectId: value })} /><ClassSelect classes={classes} value={allocation.classId} onChange={value => setAllocation({ ...allocation, classId: value })} /><YearSelect years={years} value={allocation.yearId} onChange={value => setAllocation({ ...allocation, yearId: value, termId: "" })} /><TermSelect terms={terms} yearId={allocation.yearId} value={allocation.termId} onChange={value => setAllocation({ ...allocation, termId: value })} /><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={assign.isPending}>{assign.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <BookOpenCheck className="mr-2 h-4 w-4" />}Save teaching allocation</Button></form></WorkflowCard><WorkflowCard title="Department & staff attendance" copy="Maintain a teacher’s department and record today’s staff attendance from the Teachers workspace."><div className="grid gap-3 sm:grid-cols-2"><TeacherSelect teachers={teacherRows} value={attendance.teacherId} onChange={value => setAttendance({ ...attendance, teacherId: value })} /><Select value={attendance.status} onValueChange={value => setAttendance({ ...attendance, status: value as typeof attendance.status })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent>{["present", "absent", "late", "on_leave"].map(value => <SelectItem key={value} value={value}>{value.replaceAll("_", " ")}</SelectItem>)}</SelectContent></Select><Select value={staffDepartmentId} onValueChange={setStaffDepartmentId}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Department for selected teacher" /></SelectTrigger><SelectContent>{departments.map(department => <SelectItem key={department.id} value={String(department.id)}>{department.name}</SelectItem>)}</SelectContent></Select><Button className="rounded-xl bg-[#0d4437] text-white" disabled={!attendance.teacherId || setDepartment.isPending} onClick={() => setDepartment.mutate({ teacherId: Number(attendance.teacherId), departmentId: staffDepartmentId ? Number(staffDepartmentId) : null })}>Save department</Button><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={!attendance.teacherId || recordAttendance.isPending} onClick={() => recordAttendance.mutate({ teacherId: Number(attendance.teacherId), attendanceDate: today, status: attendance.status })}>Record today’s attendance</Button></div></WorkflowCard><WorkflowCard title="Edit or remove a teacher" copy="Use inactive status to preserve linked history. Permanent removal is blocked by the server when operational records exist."><div className="grid gap-3 sm:grid-cols-2"><Select value={edit.id} onValueChange={value => { const item = teacherRows.find(row => row.id === Number(value)); if (item) setEdit({ id: value, employeeNo: item.employeeNo, firstName: item.firstName, lastName: item.lastName, phone: item.phone ?? "", email: item.email ?? "", employmentStatus: item.status }); }}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select teacher" /></SelectTrigger><SelectContent>{teacherRows.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.firstName} {item.lastName} · {item.employeeNo}</SelectItem>)}</SelectContent></Select><Select value={edit.employmentStatus} onValueChange={value => setEdit({ ...edit, employmentStatus: value as typeof edit.employmentStatus })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="active">Active</SelectItem><SelectItem value="on_leave">On leave</SelectItem><SelectItem value="inactive">Inactive</SelectItem></SelectContent></Select><Input value={edit.employeeNo} onChange={event => setEdit({ ...edit, employeeNo: event.target.value })} placeholder="Employee number" className="rounded-xl" /><Input value={edit.firstName} onChange={event => setEdit({ ...edit, firstName: event.target.value })} placeholder="First name" className="rounded-xl" /><Input value={edit.lastName} onChange={event => setEdit({ ...edit, lastName: event.target.value })} placeholder="Last name" className="rounded-xl" /><Input value={edit.phone} onChange={event => setEdit({ ...edit, phone: event.target.value })} placeholder="Phone number" className="rounded-xl" /><Input type="email" value={edit.email} onChange={event => setEdit({ ...edit, email: event.target.value })} placeholder="Email address" className="rounded-xl sm:col-span-2" /><div className="flex gap-2 sm:col-span-2"><Button className="flex-1 rounded-xl bg-[#0d4437] text-white" disabled={!edit.id || update.isPending} onClick={() => update.mutate({ teacherId: Number(edit.id), employeeNo: edit.employeeNo, firstName: edit.firstName, lastName: edit.lastName, phone: edit.phone || null, email: edit.email || null, employmentStatus: edit.employmentStatus })}>Save teacher</Button><Button variant="outline" className="rounded-xl border-rose-200 text-rose-700 hover:bg-rose-50" disabled={!edit.id || remove.isPending} onClick={() => window.confirm("Remove this teacher permanently? Historical links will block removal.") && remove.mutate({ teacherId: Number(edit.id) })}>Remove</Button></div></div></WorkflowCard></div>;
}

export function AcademicWorkflowEntry() {
  const config = trpc.school.academics.config.useQuery();
  const teachers = trpc.school.teachers.list.useQuery();
  const students = trpc.school.students.list.useQuery({ status: "active" });
  const assessments = trpc.school.academics.assessmentList.useQuery();
  const [allocation, setAllocation] = useState({ yearId: "", termId: "", classId: "", targetForm: "", title: "", type: "test" as "exam" | "test" | "assignment", maxMarks: "100", date: today });
  const [mark, setMark] = useState({ assessmentId: "", studentId: "", subjectId: "", score: "" });
  const [subject, setSubject] = useState({ id: "", code: "", name: "", category: "compulsory" as "compulsory" | "optional", isActive: true });
  const [classForm, setClassForm] = useState({ id: "", capacity: "45", classTeacherId: "" });
  const createAssessment = trpc.school.academics.createAssessment.useMutation({ onSuccess: () => { toast.success("Assessment created for the selected class or form. Add the next assessment when ready."); setAllocation({ yearId: "", termId: "", classId: "", targetForm: "", title: "", type: "test", maxMarks: "100", date: today }); assessments.refetch(); }, onError: error => toast.error(error.message) });
  const enterMark = trpc.school.academics.enterMark.useMutation({ onSuccess: result => { toast.success("Mark saved as " + result.grade + ". Ready for the next learner."); setMark(current => ({ ...current, studentId: "", score: "" })); }, onError: error => toast.error(error.message) });
  const updateSubject = trpc.school.academics.updateSubject.useMutation({ onSuccess: () => { toast.success("Subject updated."); setSubject({ id: "", code: "", name: "", category: "compulsory", isActive: true }); config.refetch(); }, onError: error => toast.error(error.message) });
  const removeSubject = trpc.school.academics.removeSubject.useMutation({ onSuccess: () => { toast.success("Subject removed."); setSubject({ id: "", code: "", name: "", category: "compulsory", isActive: true }); config.refetch(); }, onError: error => toast.error(error.message) });
  const updateClass = trpc.school.academics.updateClass.useMutation({ onSuccess: () => { toast.success("Class settings updated."); setClassForm({ id: "", capacity: "45", classTeacherId: "" }); config.refetch(); }, onError: error => toast.error(error.message) });
  const classes = config.data?.classes ?? [];
  const subjects = config.data?.subjects ?? [];
  const years = config.data?.academicYears ?? [];
  const terms = config.data?.terms ?? [];
  const teacherRows = teachers.data ?? [];
  return <div className="mb-6 grid gap-5 xl:grid-cols-2"><WorkflowCard title="Assessment setup" copy="Create an exam, test, or assignment for a configured year, term, and audience. Choose one class, or schedule it for all streams in Form 1, Form 2, Form 3, or Form 4. The next form is ready after every save."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (![allocation.yearId, allocation.termId, allocation.title].every(Boolean) || (!allocation.classId && !allocation.targetForm)) return toast.error("Complete the year, term, audience, title, and date fields."); createAssessment.mutate({ academicYearId: Number(allocation.yearId), termId: Number(allocation.termId), ...(allocation.targetForm ? { targetForm: allocation.targetForm as "Form 1" | "Form 2" | "Form 3" | "Form 4" } : { classId: Number(allocation.classId) }), title: allocation.title, assessmentType: allocation.type, maxMarks: Number(allocation.maxMarks), assessmentDate: allocation.date }); }}><YearSelect years={years} value={allocation.yearId} onChange={value => setAllocation({ ...allocation, yearId: value, termId: "" })} /><TermSelect terms={terms} yearId={allocation.yearId} value={allocation.termId} onChange={value => setAllocation({ ...allocation, termId: value })} /><div className="grid gap-3 sm:grid-cols-2"><ClassSelect classes={classes} value={allocation.classId} onChange={value => setAllocation({ ...allocation, classId: value, targetForm: "" })} /><Select value={allocation.targetForm || "none"} onValueChange={value => setAllocation({ ...allocation, targetForm: value === "none" ? "" : value, classId: "" })}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Or target an entire form" /></SelectTrigger><SelectContent><SelectItem value="none">Single class only</SelectItem>{["Form 1", "Form 2", "Form 3", "Form 4"].map(value => <SelectItem key={value} value={value}>{`All ${value}s`}</SelectItem>)}</SelectContent></Select></div><Select value={allocation.type} onValueChange={value => setAllocation({ ...allocation, type: value as typeof allocation.type })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="test">Test</SelectItem><SelectItem value="exam">Exam</SelectItem><SelectItem value="assignment">Assignment</SelectItem></SelectContent></Select><Input value={allocation.title} onChange={event => setAllocation({ ...allocation, title: event.target.value })} placeholder="Assessment title" className="rounded-xl" required /><Input type="number" min="1" value={allocation.maxMarks} onChange={event => setAllocation({ ...allocation, maxMarks: event.target.value })} placeholder="Maximum marks" className="rounded-xl" required /><Input type="date" value={allocation.date} onChange={event => setAllocation({ ...allocation, date: event.target.value })} className="rounded-xl" /><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={createAssessment.isPending}>{createAssessment.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Plus className="mr-2 h-4 w-4" />}Create assessment</Button></form></WorkflowCard><WorkflowCard title="Restricted marks entry" copy="Teacher allocations and assessment ownership are checked server-side before a grade-ready mark is saved."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (![mark.assessmentId, mark.studentId, mark.subjectId, mark.score].every(Boolean)) return toast.error("Complete all mark fields."); enterMark.mutate({ assessmentId: Number(mark.assessmentId), studentId: Number(mark.studentId), subjectId: Number(mark.subjectId), score: Number(mark.score) }); }}><Select value={mark.assessmentId} onValueChange={value => setMark({ ...mark, assessmentId: value })}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Assessment" /></SelectTrigger><SelectContent>{assessments.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.title} · {item.form} {item.stream}</SelectItem>)}</SelectContent></Select><StudentSelect students={students.data ?? []} value={mark.studentId} onChange={value => setMark({ ...mark, studentId: value })} /><SubjectSelect subjects={subjects} value={mark.subjectId} onChange={value => setMark({ ...mark, subjectId: value })} /><Input type="number" min="0" value={mark.score} onChange={event => setMark({ ...mark, score: event.target.value })} placeholder="Score" className="rounded-xl" required /><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={enterMark.isPending}>{enterMark.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}Save grade-ready mark</Button></form></WorkflowCard><WorkflowCard title="Edit or remove a subject" copy="Keep subject corrections in Academics. Removal is only available when no learner, timetable, mark, or assignment links exist."><div className="grid gap-3 sm:grid-cols-2"><Select value={subject.id} onValueChange={value => { const item = subjects.find(row => row.id === Number(value)); if (item) setSubject({ id: value, code: item.code, name: item.name, category: item.category, isActive: item.isActive }); }}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select subject" /></SelectTrigger><SelectContent>{subjects.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.name} · {item.code}</SelectItem>)}</SelectContent></Select><Select value={subject.category} onValueChange={value => setSubject({ ...subject, category: value as typeof subject.category })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="compulsory">Compulsory</SelectItem><SelectItem value="optional">Optional</SelectItem></SelectContent></Select><Input value={subject.code} onChange={event => setSubject({ ...subject, code: event.target.value.toUpperCase() })} placeholder="Subject code" className="rounded-xl" /><Input value={subject.name} onChange={event => setSubject({ ...subject, name: event.target.value })} placeholder="Subject name" className="rounded-xl" /><Select value={subject.isActive ? "active" : "inactive"} onValueChange={value => setSubject({ ...subject, isActive: value === "active" })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="active">Active</SelectItem><SelectItem value="inactive">Inactive / archived</SelectItem></SelectContent></Select><div className="flex gap-2"><Button className="flex-1 rounded-xl bg-[#0d4437] text-white" disabled={!subject.id || updateSubject.isPending} onClick={() => updateSubject.mutate({ subjectId: Number(subject.id), code: subject.code, name: subject.name, category: subject.category, isActive: subject.isActive })}>Save changes</Button><Button variant="outline" className="rounded-xl border-rose-200 text-rose-700 hover:bg-rose-50" disabled={!subject.id || removeSubject.isPending} onClick={() => window.confirm("Remove this subject permanently? Subjects with linked data cannot be removed.") && removeSubject.mutate({ subjectId: Number(subject.id) })}>Remove</Button></div></div></WorkflowCard><WorkflowCard title="Class capacity & class teacher" copy="Assign an active class teacher and update intake capacity within Academics. Linked records are preserved by the server."><div className="grid gap-3 sm:grid-cols-2"><Select value={classForm.id} onValueChange={value => { const item = classes.find(row => row.id === Number(value)); if (item) setClassForm({ id: value, capacity: String(item.capacity), classTeacherId: item.classTeacherId ? String(item.classTeacherId) : "" }); }}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select class" /></SelectTrigger><SelectContent>{classes.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.form} · {item.stream}</SelectItem>)}</SelectContent></Select><Input type="number" min="1" max="120" value={classForm.capacity} onChange={event => setClassForm({ ...classForm, capacity: event.target.value })} placeholder="Capacity" className="rounded-xl" /><Select value={classForm.classTeacherId} onValueChange={value => setClassForm({ ...classForm, classTeacherId: value })}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Assign class teacher" /></SelectTrigger><SelectContent>{teacherRows.filter(teacher => teacher.status === "active").map(teacher => <SelectItem key={teacher.id} value={String(teacher.id)}>{teacher.firstName} {teacher.lastName}</SelectItem>)}</SelectContent></Select><div className="flex gap-2"><Button className="flex-1 rounded-xl bg-[#0d4437] text-white" disabled={!classForm.id || updateClass.isPending} onClick={() => updateClass.mutate({ classId: Number(classForm.id), capacity: Number(classForm.capacity), classTeacherId: classForm.classTeacherId ? Number(classForm.classTeacherId) : null })}>Save class settings</Button><Button variant="outline" className="rounded-xl" disabled={!classForm.id || updateClass.isPending} onClick={() => updateClass.mutate({ classId: Number(classForm.id), capacity: Number(classForm.capacity), classTeacherId: null })}>Clear teacher</Button></div></div></WorkflowCard></div>;
}

export function SubjectExamMarksEntry() {
  const config = trpc.school.academics.config.useQuery();
  const assessments = trpc.school.academics.assessmentList.useQuery();
  const [form, setForm] = useState({ assessmentId: "", studentId: "", subjectId: "", score: "", comment: "" });
  const selectedAssessment = assessments.data?.find(item => item.id === Number(form.assessmentId));
  const students = trpc.school.students.list.useQuery({ classId: selectedAssessment?.classId ?? 0, status: "active" }, { enabled: Boolean(selectedAssessment) });
  const save = trpc.school.academics.enterMark.useMutation({ onSuccess: result => { toast.success(`Mark saved as ${result.grade}. Select the next learner for this subject.`); setForm(current => ({ ...current, studentId: "", score: "", comment: "" })); }, onError: error => toast.error(error.message) });
  const subjects = config.data?.subjects ?? [];
  return <WorkflowCard title="Examination marks by subject" copy="Choose the examination first. The learner list then narrows to that assessment’s class, and the server confirms your teaching allocation before it saves or updates a mark."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (!selectedAssessment || !form.studentId || !form.subjectId || form.score === "") return toast.error("Select an examination, learner, subject, and score."); save.mutate({ assessmentId: selectedAssessment.id, studentId: Number(form.studentId), subjectId: Number(form.subjectId), score: Number(form.score), comment: form.comment.trim() || undefined }); }}><div className="sm:col-span-2"><Label>Examination or assessment</Label><Select value={form.assessmentId} onValueChange={value => setForm({ assessmentId: value, studentId: "", subjectId: "", score: "", comment: "" })}><SelectTrigger className="mt-2 rounded-xl"><SelectValue placeholder="Select an examination" /></SelectTrigger><SelectContent>{assessments.data?.map(item => <SelectItem key={item.id} value={String(item.id)}>{item.title} · {item.type} · {item.form} {item.stream} · max {item.maxMarks}</SelectItem>)}</SelectContent></Select></div>{selectedAssessment ? <div className="sm:col-span-2 rounded-xl bg-[#f4f7f5] px-3 py-2 text-xs text-slate-600 dark:bg-white/5 dark:text-slate-300">Entering marks for <strong>{selectedAssessment.form} {selectedAssessment.stream}</strong>. Each subject score must be between 0 and {selectedAssessment.maxMarks}.</div> : null}<div><Label>Learner</Label><div className="mt-2"><StudentSelect students={students.data ?? []} value={form.studentId} onChange={value => setForm({ ...form, studentId: value })} /></div></div><div><Label>Subject</Label><div className="mt-2"><SubjectSelect subjects={subjects} value={form.subjectId} onChange={value => setForm({ ...form, subjectId: value })} /></div></div><div><Label>Score</Label><Input className="mt-2 rounded-xl" type="number" min="0" max={selectedAssessment?.maxMarks ?? undefined} value={form.score} onChange={event => setForm({ ...form, score: event.target.value })} placeholder={selectedAssessment ? `0–${selectedAssessment.maxMarks}` : "Select examination first"} required /></div><div><Label>Teacher comment <span className="text-slate-400">(optional)</span></Label><Input className="mt-2 rounded-xl" maxLength={500} value={form.comment} onChange={event => setForm({ ...form, comment: event.target.value })} placeholder="Brief feedback" /></div><Button type="submit" className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={!selectedAssessment || save.isPending}>{save.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}Save subject mark</Button></form></WorkflowCard>;
}

export function AttendanceExceptionEntry() {
  const config = trpc.school.academics.config.useQuery();
  const students = trpc.school.students.list.useQuery({});
  const [form, setForm] = useState({ classId: "", studentId: "", status: "absent" as "present" | "absent" | "late", reason: "", date: today });
  const mark = trpc.school.attendance.mark.useMutation({ onSuccess: () => { toast.success("Attendance record saved. Ready for the next learner."); setForm(current => ({ ...current, studentId: "", status: "absent", reason: "" })); }, onError: error => toast.error(error.message) });
  const selectedStudents = students.data?.filter(student => !form.classId || student.classId === Number(form.classId)) ?? [];
  const classes = config.data?.classes ?? [];
  return <WorkflowCard title="Attendance exception" copy="Record an individual present, late, or absent learner with an optional absence reason. Full-class capture remains above in Attendance."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (![form.classId, form.studentId].every(Boolean)) return toast.error("Select a class and learner."); mark.mutate({ classId: Number(form.classId), attendanceDate: form.date, records: [{ studentId: Number(form.studentId), status: form.status, absenceReason: form.status === "absent" ? form.reason || undefined : undefined }] }); }}><ClassSelect classes={classes} value={form.classId} onChange={value => setForm({ ...form, classId: value, studentId: "" })} /><StudentSelect students={selectedStudents} value={form.studentId} onChange={value => setForm({ ...form, studentId: value })} /><Select value={form.status} onValueChange={value => setForm({ ...form, status: value as typeof form.status })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="present">Present</SelectItem><SelectItem value="late">Late</SelectItem><SelectItem value="absent">Absent</SelectItem></SelectContent></Select><Input type="date" value={form.date} onChange={event => setForm({ ...form, date: event.target.value })} className="rounded-xl" /><Input value={form.reason} onChange={event => setForm({ ...form, reason: event.target.value })} placeholder="Absence reason (when absent)" className="rounded-xl sm:col-span-2" /><Button className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={mark.isPending}>{mark.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}Save attendance record</Button></form></WorkflowCard>;
}

export function TimetableEntry() {
  const config = trpc.school.academics.config.useQuery();
  const teachers = trpc.school.teachers.list.useQuery();
  const [slot, setSlot] = useState({ yearId: "", termId: "", classId: "", subjectId: "", teacherId: "", room: "", day: "Monday" as "Monday" | "Tuesday" | "Wednesday" | "Thursday" | "Friday" | "Saturday" | "Sunday", startsAt: "08:00", endsAt: "08:40" });
  const create = trpc.school.timetable.createSlot.useMutation({ onSuccess: () => { toast.success("Timetable slot created without conflicts. Ready for the next slot."); setSlot(current => ({ ...current, subjectId: "", teacherId: "", room: "", startsAt: "08:00", endsAt: "08:40" })); }, onError: error => toast.error(error.message) });
  const classes = config.data?.classes ?? [];
  const subjects = config.data?.subjects ?? [];
  const years = config.data?.academicYears ?? [];
  const terms = config.data?.terms ?? [];
  return <WorkflowCard title="Conflict-checked timetable slot" copy="Create a class, teacher, subject, and room session. The server refuses overlapping teacher, class, or room bookings."><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3" onSubmit={event => { event.preventDefault(); if (![slot.yearId, slot.termId, slot.classId, slot.subjectId, slot.teacherId, slot.room].every(Boolean)) return toast.error("Complete all timetable fields."); create.mutate({ academicYearId: Number(slot.yearId), termId: Number(slot.termId), classId: Number(slot.classId), subjectId: Number(slot.subjectId), teacherId: Number(slot.teacherId), room: slot.room, dayOfWeek: slot.day, startsAt: slot.startsAt, endsAt: slot.endsAt }); }}><YearSelect years={years} value={slot.yearId} onChange={value => setSlot({ ...slot, yearId: value, termId: "" })} /><TermSelect terms={terms} yearId={slot.yearId} value={slot.termId} onChange={value => setSlot({ ...slot, termId: value })} /><ClassSelect classes={classes} value={slot.classId} onChange={value => setSlot({ ...slot, classId: value })} /><SubjectSelect subjects={subjects} value={slot.subjectId} onChange={value => setSlot({ ...slot, subjectId: value })} /><TeacherSelect teachers={teachers.data ?? []} value={slot.teacherId} onChange={value => setSlot({ ...slot, teacherId: value })} /><Input value={slot.room} onChange={event => setSlot({ ...slot, room: event.target.value })} placeholder="Room" className="rounded-xl" required /><Select value={slot.day} onValueChange={value => setSlot({ ...slot, day: value as typeof slot.day })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent>{["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"].map(day => <SelectItem key={day} value={day}>{day}</SelectItem>)}</SelectContent></Select><Input type="time" value={slot.startsAt} onChange={event => setSlot({ ...slot, startsAt: event.target.value })} className="rounded-xl" /><Input type="time" value={slot.endsAt} onChange={event => setSlot({ ...slot, endsAt: event.target.value })} className="rounded-xl" /><Button className="rounded-xl bg-[#0d4437] text-white lg:col-span-3" disabled={create.isPending}>{create.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CalendarDays className="mr-2 h-4 w-4" />}Create clash-free timetable slot</Button></form></WorkflowCard>;
}

export function InsightsReportEntry() {
  const config = trpc.school.academics.config.useQuery();
  const [classId, setClassId] = useState("");
  const performance = trpc.school.academics.performance.useQuery({ classId: Number(classId || 0) }, { enabled: Boolean(classId) });
  const attendance = trpc.school.attendance.classSummary.useQuery({ classId: Number(classId || 0) }, { enabled: Boolean(classId) });
  const classes = config.data?.classes ?? [];
  return <WorkflowCard title="Class performance & attendance flags" copy="Review normalized subject performance, attendance rates, and repeated-absence signals. Fees, attendance capture, and academic entry remain in their primary workspaces."><ClassSelect classes={classes} value={classId} onChange={setClassId} />{classId && performance.data?.length ? <div className="mt-4 grid gap-2 sm:grid-cols-2">{performance.data.map(item => <div key={item.subjectId} className="rounded-xl bg-[#f4f7f5] p-3 dark:bg-white/5"><p className="text-sm font-semibold">{item.subject}</p><p className="mt-1 text-lg font-semibold text-[#0d4437] dark:text-emerald-300">{item.average}%</p><p className="text-xs text-slate-500">{item.learnersMarked} entries · mean points {item.meanPoints}</p></div>)}</div> : <p className="mt-4 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">Select a class and enter marks to view subject performance.</p>}{classId && attendance.data ? <div className="mt-3 grid gap-2 sm:grid-cols-3"><Metric label="Attendance rate" value={attendance.data.rate + "%"} /><Metric label="Absences" value={String(attendance.data.absences)} /><Metric label="Repeated flags" value={String(attendance.data.repeatedAbsenceStudentIds.length)} /></div> : null}</WorkflowCard>;
}

function Metric({ label, value }: { label: string; value: string }) {
  return <div className="rounded-xl bg-[#f4f7f5] p-4 dark:bg-white/5"><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">{label}</p><p className="mt-2 text-lg font-semibold text-[#143b31] dark:text-emerald-50">{value}</p></div>;
}

export function FeesCollectionReport() {
  const collection = trpc.school.finance.collectionSummary.useQuery();
  return <Card className="mb-6 border-emerald-950/8 bg-white/85 dark:border-white/8 dark:bg-[#172420]"><CardHeader className="pb-3"><CardTitle className="text-base text-[#143b31] dark:text-emerald-50">Collection report</CardTitle><CardDescription>Whole-school collections by payment method. Detailed learner balances, payments, statements, and receipts remain in this Fees workspace.</CardDescription></CardHeader><CardContent><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Total collected" value={formatKes(collection.data?.total)} /><Metric label="Receipts" value={String(collection.data?.payments ?? 0)} />{Object.entries(collection.data?.byMethod ?? {}).map(([method, amount]) => <Metric key={method} label={method.toUpperCase()} value={formatKes(amount)} />)}</div></CardContent></Card>;
}

export function AnnouncementTargetingEntry() {
  const config = trpc.school.academics.config.useQuery();
  const [form, setForm] = useState({ targetScope: "school" as "school" | "form" | "class" | "teachers" | "parents" | "students", targetForm: "", classId: "", title: "", body: "" });
  const publish = trpc.school.communication.publishAnnouncement.useMutation({ onSuccess: () => { toast.success("Targeted announcement published. Ready for the next notice."); setForm({ targetScope: "school", targetForm: "", classId: "", title: "", body: "" }); }, onError: error => toast.error(error.message) });
  const classes = config.data?.classes ?? [];
  return <WorkflowCard title="Target an announcement" copy="Publish to the whole school, a form, one class, staff, parents, or students. Recipients receive an in-app notification and the action is audited."><form className="grid gap-3 sm:grid-cols-2" onSubmit={event => { event.preventDefault(); if (!form.title.trim() || !form.body.trim()) return toast.error("Provide a notice title and message."); publish.mutate({ targetScope: form.targetScope, targetForm: form.targetScope === "form" ? form.targetForm as "Form 1" | "Form 2" | "Form 3" | "Form 4" : undefined, targetClassId: form.targetScope === "class" && form.classId ? Number(form.classId) : undefined, title: form.title.trim(), body: form.body.trim() }); }}><Select value={form.targetScope} onValueChange={value => setForm({ ...form, targetScope: value as typeof form.targetScope, targetForm: "", classId: "" })}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="school">Entire school</SelectItem><SelectItem value="form">Specific form</SelectItem><SelectItem value="class">Specific class</SelectItem><SelectItem value="teachers">Teachers</SelectItem><SelectItem value="parents">Parents</SelectItem><SelectItem value="students">Students</SelectItem></SelectContent></Select>{form.targetScope === "form" ? <Select value={form.targetForm} onValueChange={value => setForm({ ...form, targetForm: value })}><SelectTrigger className="rounded-xl"><SelectValue placeholder="Select form" /></SelectTrigger><SelectContent>{["Form 1", "Form 2", "Form 3", "Form 4"].map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select> : null}{form.targetScope === "class" ? <ClassSelect classes={classes} value={form.classId} onChange={value => setForm({ ...form, classId: value })} /> : null}<Input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} placeholder="Notice title" className="rounded-xl sm:col-span-2" required /><Textarea value={form.body} onChange={event => setForm({ ...form, body: event.target.value })} placeholder="Write a clear, specific message" className="min-h-28 rounded-xl sm:col-span-2" required /><Button type="submit" className="rounded-xl bg-[#0d4437] text-white sm:col-span-2" disabled={publish.isPending}>{publish.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Plus className="mr-2 h-4 w-4" />}Publish targeted notice</Button></form></WorkflowCard>;
}

export function DailyTasksSummary() {
  return <><Card className="border-emerald-950/8 bg-white/85 dark:border-white/8 dark:bg-[#172420]"><CardHeader><CardTitle className="text-base text-[#143b31] dark:text-emerald-50">Start with the primary module</CardTitle><CardDescription>Daily tasks now live beside the records they change. Choose Students, Teachers, Academics, Attendance, Fees, Timetable, or Announcements from the navigation.</CardDescription></CardHeader><CardContent className="grid gap-3 sm:grid-cols-3"><div className="rounded-2xl bg-[#e8f1ec] p-4 dark:bg-emerald-950/40"><Users className="h-5 w-5 text-[#0d4437] dark:text-emerald-300" /><p className="mt-3 text-sm font-semibold">People</p><p className="mt-1 text-xs leading-5 text-slate-500 dark:text-slate-400">Register learners, guardians, teachers, and allocations in their own workspaces.</p></div><div className="rounded-2xl bg-[#fbf1d8] p-4 dark:bg-amber-950/30"><BookOpenCheck className="h-5 w-5 text-[#94651f] dark:text-amber-300" /><p className="mt-3 text-sm font-semibold">Records</p><p className="mt-1 text-xs leading-5 text-slate-500 dark:text-slate-400">Assessments, attendance, fees, timetable entries, and notices stay with their source module.</p></div><div className="rounded-2xl bg-[#eef4f8] p-4 dark:bg-sky-950/30"><ShieldCheck className="h-5 w-5 text-sky-700 dark:text-sky-300" /><p className="mt-3 text-sm font-semibold">Protected actions</p><p className="mt-1 text-xs leading-5 text-slate-500 dark:text-slate-400">Role checks, school scoping, and audit events remain enforced on every save.</p></div></CardContent></Card></>;
}


export function ClassPerformanceRanking() {
  const config = trpc.school.academics.config.useQuery();
  const [scope, setScope] = useState({ academicYearId: "", termId: "" });
  const overview = trpc.school.academics.classPerformanceOverview.useQuery({ academicYearId: Number(scope.academicYearId), termId: Number(scope.termId) }, { enabled: Boolean(scope.academicYearId && scope.termId) });
  const trends = trpc.school.academics.classPerformanceTrends.useQuery({ academicYearId: Number(scope.academicYearId) }, { enabled: Boolean(scope.academicYearId) });
  const [comparisonClassIds, setComparisonClassIds] = useState<number[]>([]);
  const toggleComparisonClass = (classId: number) => setComparisonClassIds(current => current.includes(classId) ? current.filter(id => id !== classId) : current.length >= 4 ? (toast.info("Compare up to four classes at a time."), current) : [...current, classId]);
  const years = config.data?.academicYears ?? [];
  const terms = config.data?.terms ?? [];
  return <WorkflowCard title="Class means & subject ranking" copy="Select an academic year and term to compare all configured classes. Averages are normalized by each assessment’s maximum score; subjects are ranked from the strongest mean percentage to the lowest."><div className="grid gap-3 sm:grid-cols-2"><YearSelect years={years} value={scope.academicYearId} onChange={value => setScope({ academicYearId: value, termId: "" })} /><TermSelect terms={terms} yearId={scope.academicYearId} value={scope.termId} onChange={value => setScope({ ...scope, termId: value })} /></div>{!scope.academicYearId || !scope.termId ? <p className="mt-4 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">Choose an academic year and term to calculate class mean grades, average percentages, and subject positions.</p> : overview.isLoading ? <p className="mt-4 text-sm text-slate-500">Calculating class performance…</p> : overview.data ? <div className="mt-4 space-y-5"><div><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold">All class performance</p><Badge className="border-0 bg-[#e8f1ec] text-[#0d4437] dark:bg-emerald-950/60 dark:text-emerald-300">{overview.data.totalMarkEntries} mark entries</Badge></div><div className="mt-3 grid gap-2 sm:grid-cols-2 xl:grid-cols-3">{overview.data.classSummaries.map(item => <div key={item.classId} className="rounded-xl border border-emerald-950/8 bg-[#f4f7f5] p-3 dark:border-white/8 dark:bg-white/5"><div className="flex items-start justify-between gap-2"><p className="text-sm font-semibold">{item.form} · {item.stream}</p><Badge className="border-0 bg-[#fbf1d8] text-[#94651f] dark:bg-amber-950/50 dark:text-amber-300">{item.meanGrade ?? "—"}</Badge></div><p className="mt-3 text-2xl font-semibold tracking-[-0.04em] text-[#0d4437] dark:text-emerald-300">{item.averagePercentage}%</p><p className="mt-1 text-xs text-slate-500">Mean points {item.meanPoints} · {item.entries} mark{item.entries === 1 ? "" : "s"}</p></div>)}</div></div><div><p className="text-sm font-semibold">Subjects: strongest to weakest</p>{overview.data.subjectRanking.length ? <ol className="mt-3 space-y-2">{overview.data.subjectRanking.map(item => <li key={item.subjectId} className="flex items-center gap-3 rounded-xl border border-emerald-950/8 px-3 py-3 dark:border-white/8"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#0d4437] text-xs font-bold text-white">{item.rank}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{item.subject}</p><p className="mt-0.5 text-xs text-slate-500">{item.entries} mark{item.entries === 1 ? "" : "s"} · mean points {item.meanPoints}</p></div><div className="text-right"><p className="text-sm font-semibold text-[#0d4437] dark:text-emerald-300">{item.averagePercentage}%</p><Badge className="mt-1 border-0 bg-[#fbf1d8] text-[#94651f] dark:bg-amber-950/50 dark:text-amber-300">{item.meanGrade}</Badge></div></li>)}</ol> : <p className="mt-3 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">No marks have been entered for this term yet.</p>}</div><div className="border-t border-emerald-950/8 pt-5 dark:border-white/8"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-semibold">Term-over-term class trends</p><p className="mt-1 text-xs text-slate-500">Normalized average percentage for every term in the selected academic year.</p></div><Badge className="border-0 bg-[#e8f1ec] text-[#0d4437] dark:bg-emerald-950/60 dark:text-emerald-300">{trends.data?.classTrends.length ?? 0} classes</Badge></div>{trends.isLoading ? <p className="mt-3 text-sm text-slate-500">Calculating term trends…</p> : trends.data?.classTrends.length ? <div><div className="mt-4 grid gap-3 lg:grid-cols-2">{trends.data.classTrends.map(item => <div key={item.class.id} className="rounded-2xl border border-emerald-950/8 bg-[#f4f7f5] p-4 dark:border-white/8 dark:bg-white/5"><div className="flex items-center justify-between gap-2"><p className="text-sm font-semibold">{item.class.form} · {item.class.stream}</p><span className="text-[10px] uppercase tracking-[0.12em] text-slate-400">Mean % by term</span></div><div className="mt-4 grid grid-cols-3 gap-2">{item.points.map(point => <div key={point.termId} className="min-w-0 text-center"><div className="flex h-24 items-end justify-center rounded-xl bg-white/70 px-2 pb-2 dark:bg-[#172420]"><div className="w-full max-w-8 rounded-t-lg bg-[#0d4437] transition-[height] duration-300" style={{ height: `${point.entries ? Math.max(8, point.averagePercentage) : 5}%` }} title={`${point.term}: ${point.averagePercentage}%`} /></div><p className="mt-2 truncate text-xs font-semibold">{point.term}</p><p className="text-xs text-slate-500">{point.entries ? `${point.averagePercentage}%` : "—"}</p><Badge className="mt-1 border-0 bg-[#fbf1d8] text-[#94651f] dark:bg-amber-950/50 dark:text-amber-300">{point.meanGrade ?? "—"}</Badge></div>)}</div></div>)}</div><div className="mt-5 border-t border-emerald-950/8 pt-5 dark:border-white/8"><div className="flex items-start justify-between gap-3"><div><p className="text-sm font-semibold">Compare classes</p><p className="mt-1 text-xs text-slate-500">Select two to four classes to compare their term averages on the same scale.</p></div><Badge className="border-0 bg-[#fbf1d8] text-[#94651f] dark:bg-amber-950/50 dark:text-amber-300">{comparisonClassIds.length}/4 selected</Badge></div><div className="mt-3 flex flex-wrap gap-2">{trends.data.classTrends.map((item, index) => <Button key={item.class.id} type="button" size="sm" variant={comparisonClassIds.includes(item.class.id) ? "default" : "outline"} className={cn("rounded-xl", comparisonClassIds.includes(item.class.id) ? "bg-[#0d4437] text-white hover:bg-[#092f26]" : "bg-white dark:bg-transparent")} onClick={() => toggleComparisonClass(item.class.id)}>{item.class.form} · {item.class.stream}</Button>)}</div>{comparisonClassIds.length < 2 ? <p className="mt-3 rounded-xl border border-dashed border-emerald-950/12 p-3 text-xs text-slate-500 dark:border-white/12 dark:text-slate-400">Choose at least two classes to see a direct comparison.</p> : <div className="mt-4 overflow-x-auto"><div className="min-w-[560px] space-y-3">{(trends.data.classTrends.find(item => item.class.id === comparisonClassIds[0])?.points ?? []).map((point, pointIndex) => <div key={point.termId} className="grid grid-cols-[92px_1fr] items-center gap-3"><p className="text-xs font-semibold text-slate-500">{point.term}</p><div className="space-y-1.5">{comparisonClassIds.map((classId, classIndex) => { const item = trends.data.classTrends.find(candidate => candidate.class.id === classId); const classPoint = item?.points[pointIndex]; return <div key={classId} className="flex items-center gap-2"><span className="w-28 truncate text-xs font-medium">{item?.class.form} · {item?.class.stream}</span><div className="h-2 flex-1 rounded-full bg-emerald-950/8 dark:bg-white/10"><div className={cn("h-2 rounded-full", classIndex % 3 === 0 ? "bg-[#0d4437]" : classIndex % 3 === 1 ? "bg-[#a8792c]" : "bg-[#d56b5d]")} style={{ width: `${classPoint?.entries ? Math.min(100, Math.max(0, classPoint.averagePercentage)) : 0}%` }} /></div><span className="w-12 text-right text-xs font-semibold">{classPoint?.entries ? `${classPoint.averagePercentage}%` : "—"}</span></div>; })}</div></div>)}</div></div>}</div></div> : <p className="mt-3 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">No classes or marks are available for this academic year yet.</p>}</div></div> : <p className="mt-4 rounded-xl border border-rose-200 p-4 text-sm text-rose-700">{overview.error?.message || "Performance data could not be loaded."}</p>}</WorkflowCard>;
}

type RosterPdfStudent = { firstName: string; lastName: string; admissionNo: string; form: string; stream: string; meanPercentage: number | null; subjects: Array<{ subjectId: number; subject: string; subjectCode: string; score: number | null; maxMarks: number }> };
type RosterPdfSection = { title: string; meanPercentage: number | null; students: RosterPdfStudent[] };
function escapeRosterPdf(value: unknown) { return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;"); }
function openRosterPdf(schoolName: string, reportTitle: string, termName: string, scopeMean: number | null, sections: RosterPdfSection[]) {
  const esc = escapeRosterPdf;
  const sectionHtml = sections.map(section => {
    const students = [...section.students].sort((a, b) => a.lastName.localeCompare(b.lastName) || a.firstName.localeCompare(b.firstName) || a.admissionNo.localeCompare(b.admissionNo));
    const subjects = Array.from(new Map(students.flatMap(student => student.subjects.map(subject => [subject.subjectId, subject] as const))).values()).sort((a, b) => a.subject.localeCompare(b.subject));
    const ranked = [...students].filter(student => student.meanPercentage !== null).sort((a, b) => (b.meanPercentage ?? 0) - (a.meanPercentage ?? 0));
    const rank = new Map<RosterPdfStudent, number>();
    ranked.forEach((student, index) => { if (!rank.has(student)) rank.set(student, index + 1); });
    const mean = section.meanPercentage === null ? "—" : `${section.meanPercentage.toFixed(2)}%`;
    return `<section class="class-section"><div class="section-heading"><h2>${esc(section.title)}</h2><strong>Class mean: ${mean}</strong></div><table><thead><tr><th>#</th><th>Admission no.</th><th>Learner (alphabetical)</th>${subjects.map(subject => `<th>${esc(subject.subject)}<br><small>Mark</small></th>`).join("")}<th>Mean %</th><th>Rank</th></tr></thead><tbody>${students.map((student, index) => {
      const learnerMean = student.meanPercentage === null ? "—" : `${student.meanPercentage.toFixed(2)}%`;
      const studentRank = student.meanPercentage === null ? "—" : (rank.get(student) ?? "—");
      return `<tr><td>${index + 1}</td><td>${esc(student.admissionNo)}</td><td>${esc(student.lastName)}, ${esc(student.firstName)}</td>${subjects.map(subject => { const mark = student.subjects.find(item => item.subjectId === subject.subjectId); return `<td>${mark && mark.score !== null ? `${esc(mark.score)} / ${esc(mark.maxMarks)}` : "—"}</td>`; }).join("")}<td><strong>${learnerMean}</strong></td><td>${studentRank}</td></tr>`;
    }).join("")}</tbody></table><p class="note">Roster is listed alphabetically by surname; rank is based on available subject-mark percentages.</p></section>`;
  }).join("");
  const popup = window.open("", "_blank", "width=1200,height=900");
  if (!popup) { toast.error("Allow pop-ups to print or save this results PDF."); return; }
  popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(reportTitle)}</title><style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#18382f;margin:0;padding:16px}.header{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #dfb955;padding-bottom:12px;margin-bottom:18px}.header h1{font-size:20px;margin:0 0 5px}.header p{font-size:11px;color:#64746c;margin:4px 0}.summary{border:1px solid #d7e3dc;background:#f3f7f4;padding:10px 14px;margin-bottom:18px;font-size:14px}.class-section{margin:0 0 22px;page-break-inside:avoid}.section-heading{display:flex;justify-content:space-between;align-items:center;margin:15px 0 8px}.section-heading h2{font-size:15px;margin:0}.section-heading strong{font-size:13px;color:#0d4437}table{width:100%;border-collapse:collapse;font-size:9px}thead{display:table-header-group}th,td{border:1px solid #cfdad3;padding:5px;text-align:center;vertical-align:middle}th{background:#eef4f0;font-size:8px;text-transform:uppercase;color:#52645b}td:nth-child(2),td:nth-child(3){text-align:left}tr{page-break-inside:avoid}.note{font-size:9px;color:#65756d;margin:6px 0 0}@media print{body{padding:0}.class-section{page-break-inside:auto}.class-section table{page-break-inside:auto}}</style></head><body><div class="header"><div><h1>${esc(schoolName)}</h1><p>${esc(reportTitle)} · ${esc(termName)}</p></div><div><h1>Student Results Register</h1><p>Generated ${esc(new Date().toLocaleString("en-KE"))}</p></div></div><div class="summary"><strong>Overall ${sections.length > 1 ? "form" : "class"} mean:</strong> ${scopeMean === null ? "No marks entered" : `${scopeMean.toFixed(2)}%`} · <strong>Learners listed:</strong> ${sections.reduce((sum, section) => sum + section.students.length, 0)} · Sorted alphabetically, from first learner to last.</div>${sectionHtml}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),300));</script></body></html>`);
  popup.document.close();
  popup.focus();
}

export function ReportCardWorkflowEntry() {
  const config = trpc.school.academics.config.useQuery();
  const [mode, setMode] = useState<"learner" | "class" | "form">("learner");
  const [form, setForm] = useState({ classId: "", yearId: "", termId: "", studentId: "", selectedForm: "Form 1" as "Form 1" | "Form 2" | "Form 3" | "Form 4" });
  const [rows, setRows] = useState<Array<{ subjectId: number; subject: string; subjectCode: string; score: string; maxMarks: string; comment: string }>>([]);
  const [teacherComment, setTeacherComment] = useState("");
  const [bulkMarks, setBulkMarks] = useState<Record<string, string>>({});
  const [bulkMaxMarks, setBulkMaxMarks] = useState<Record<number, string>>({});
  const [bulkComments, setBulkComments] = useState<Record<string, string>>({});
  const classId = Number(form.classId) || 0;
  const students = trpc.school.students.list.useQuery({ classId: classId || undefined, status: "active" }, { enabled: Boolean(classId && mode === "learner") });
  const sheetInput = useMemo(() => ({ studentId: Number(form.studentId), classId, academicYearId: Number(form.yearId), termId: Number(form.termId) }), [form.studentId, form.classId, form.yearId, form.termId]);
  const sheet = trpc.school.reportCards.editableSheet.useQuery(sheetInput, { enabled: Boolean(mode === "learner" && form.studentId && form.classId && form.yearId && form.termId) });
  const classSheetInput = useMemo(() => ({ academicYearId: Number(form.yearId), termId: Number(form.termId), ...(mode === "form" ? { form: form.selectedForm } : { classId }) }), [mode, form.yearId, form.termId, form.selectedForm, form.classId]);
  const classSheetEnabled = mode !== "learner" && Boolean(form.yearId && form.termId && (mode === "form" || form.classId));
  const classSheet = trpc.school.reportCards.classSheet.useQuery(classSheetInput, { enabled: classSheetEnabled });
  const utils = trpc.useUtils();
  useEffect(() => {
    if (!sheet.data || mode !== "learner") return;
    setRows(sheet.data.rows.map(row => ({ subjectId: row.subjectId, subject: row.subject, subjectCode: row.subjectCode, score: row.score === null ? "" : String(row.score), maxMarks: String(row.maxMarks), comment: row.comment ?? "" })));
    setTeacherComment(sheet.data.teacherComment);
  }, [sheet.data, mode]);
  useEffect(() => {
    if (!classSheet.data || mode !== "class") return;
    const markValues: Record<string, string> = {};
    const maxValues: Record<number, string> = {};
    const commentValues: Record<string, string> = {};
    for (const learner of classSheet.data.students) for (const mark of learner.subjects) {
      const key = `${learner.id}:${mark.subjectId}`;
      markValues[key] = mark.score === null ? "" : String(mark.score);
      commentValues[key] = mark.comment ?? "";
      if (maxValues[mark.subjectId] === undefined) maxValues[mark.subjectId] = String(mark.maxMarks || 100);
    }
    setBulkMarks(markValues);
    setBulkMaxMarks(maxValues);
    setBulkComments(commentValues);
  }, [classSheet.data, mode]);
  const save = trpc.school.reportCards.saveEditableSheet.useMutation({
    onSuccess: result => {
      const syncMessage = result.gradebookSyncedSubjectCount === result.subjectCount ? "All marks were also added to the gradebook." : `${result.gradebookSyncedSubjectCount} of ${result.subjectCount} subjects were also added to the gradebook; assign a teacher to any remaining subjects to sync them.`;
      toast.success(`Saved ${result.subjectCount} subject marks and the report-card draft (${result.overallGrade}, ${result.average}%). ${syncMessage}`);
      void utils.school.reportCards.editableSheet.invalidate();
      void utils.school.reportCards.classSheet.invalidate();
      void utils.school.reportCards.batchStatus.invalidate();
      void utils.school.reportCards.mine.invalidate();
    },
    onError: error => toast.error(error.message),
  });
  const saveClass = trpc.school.reportCards.saveClassSheet.useMutation({
    onSuccess: result => {
      toast.success(`Saved report cards for ${result.learnerCount} learners. Class mean: ${result.classMean}% (${result.meanGrade}); ${result.gradebookSyncedMarkCount} gradebook marks synchronized.`);
      void utils.school.reportCards.classSheet.invalidate();
      void utils.school.reportCards.batchStatus.invalidate();
      void utils.school.reportCards.mine.invalidate();
    },
    onError: error => toast.error(error.message),
  });
  const classes = config.data?.classes ?? [];
  const years = config.data?.academicYears ?? [];
  const terms = config.data?.terms ?? [];
  const hasScope = Boolean(form.classId && form.yearId && form.termId);
  const updateRow = (subjectId: number, patch: Partial<(typeof rows)[number]>) => setRows(current => current.map(row => row.subjectId === subjectId ? { ...row, ...patch } : row));
  const complete = Boolean(rows.length && rows.length === sheet.data?.rows.length && rows.every(row => row.score.trim() !== "" && Number.isFinite(Number(row.score)) && Number.isFinite(Number(row.maxMarks)) && Number(row.maxMarks) > 0 && Number(row.score) >= 0 && Number(row.score) <= Number(row.maxMarks)));
  const filledCount = rows.filter(row => row.score.trim() !== "").length;
  const average = filledCount ? rows.reduce((sum, row) => sum + (row.score.trim() && Number(row.maxMarks) > 0 ? Number(row.score) / Number(row.maxMarks) * 100 : 0), 0) / filledCount : 0;
  const saveSheet = (event: React.FormEvent) => {
    event.preventDefault();
    if (!complete) return toast.error("Enter a valid mark for every subject before saving the report card.");
    save.mutate({ ...sheetInput, teacherComment: teacherComment.trim() || undefined, rows: rows.map(row => ({ subjectId: row.subjectId, score: Number(row.score), maxMarks: Number(row.maxMarks), comment: row.comment.trim() || undefined })) });
  };
  const roster = classSheet.data?.students ?? [];
  const rosterSubjects = classSheet.data?.subjects ?? [];
  const bulkRequired = roster.flatMap(learner => learner.subjects.map(subject => ({ learner, subject })));
  const learnersWithoutSubjects = roster.filter(learner => learner.subjects.length === 0);
  const bulkComplete = Boolean(bulkRequired.length && bulkRequired.every(({ learner, subject }) => {
    const value = bulkMarks[`${learner.id}:${subject.subjectId}`] ?? "";
    const max = Number(bulkMaxMarks[subject.subjectId] ?? subject.maxMarks ?? 100);
    return value.trim() !== "" && Number.isFinite(Number(value)) && Number.isFinite(max) && max > 0 && Number(value) >= 0 && Number(value) <= max;
  }));
  const bulkFilled = bulkRequired.filter(({ learner, subject }) => (bulkMarks[`${learner.id}:${subject.subjectId}`] ?? "").trim() !== "").length;
  const bulkStudentMeans = new Map<number, number | null>();
  for (const learner of roster) {
    const learnerValues = learner.subjects.map(subject => {
      const value = bulkMarks[`${learner.id}:${subject.subjectId}`] ?? "";
      const max = Number(bulkMaxMarks[subject.subjectId] ?? subject.maxMarks ?? 100);
      return value.trim() && max > 0 ? Number(value) / max * 100 : null;
    }).filter((value): value is number => value !== null);
    bulkStudentMeans.set(learner.id, learnerValues.length ? learnerValues.reduce((sum, value) => sum + value, 0) / learnerValues.length : null);
  }
  const rosterMarkedMeans = roster.map(learner => bulkStudentMeans.get(learner.id)).filter((value): value is number => value !== null);
  const liveClassMean = rosterMarkedMeans.length ? rosterMarkedMeans.reduce((sum, value) => sum + value, 0) / rosterMarkedMeans.length : null;
  const saveClassSheet = () => {
    if (!classSheet.data || !bulkComplete) return toast.error("Enter a valid mark for every assigned subject for each learner before saving the whole class.");
    saveClass.mutate({ academicYearId: Number(form.yearId), termId: Number(form.termId), classId, students: roster.map(learner => ({ studentId: learner.id, rows: learner.subjects.map(subject => ({ subjectId: subject.subjectId, score: Number(bulkMarks[`${learner.id}:${subject.subjectId}`]), maxMarks: Number(bulkMaxMarks[subject.subjectId] ?? subject.maxMarks ?? 100), comment: bulkComments[`${learner.id}:${subject.subjectId}`]?.trim() || undefined })) })) });
  };
  const printResults = () => {
    if (!classSheet.data) return;
    const reportStudents: RosterPdfStudent[] = roster.map(learner => ({
      firstName: learner.firstName, lastName: learner.lastName, admissionNo: learner.admissionNo, form: learner.form, stream: learner.stream,
      meanPercentage: mode === "class" ? bulkStudentMeans.get(learner.id) ?? null : learner.meanPercentage,
      subjects: learner.subjects.map(subject => ({ subjectId: subject.subjectId, subject: subject.subject, subjectCode: subject.subjectCode, score: mode === "class" ? ((bulkMarks[`${learner.id}:${subject.subjectId}`] ?? "").trim() ? Number(bulkMarks[`${learner.id}:${subject.subjectId}`]) : null) : subject.score, maxMarks: mode === "class" ? Number(bulkMaxMarks[subject.subjectId] ?? subject.maxMarks ?? 100) : subject.maxMarks })),
    }));
    const sections: RosterPdfSection[] = (mode === "form" ? [...classSheet.data.classes].sort((a, b) => a.form.localeCompare(b.form, undefined, { numeric: true }) || a.stream.localeCompare(b.stream)) : classSheet.data.classes.slice(0, 1)).map(classRow => {
      const classStudents = reportStudents.filter(student => student.form === classRow.form && student.stream === classRow.stream);
      const means = classStudents.map(student => student.meanPercentage).filter((value): value is number => value !== null);
      return { title: `${classRow.form} · ${classRow.stream} (${classStudents.length} learners)`, meanPercentage: means.length ? means.reduce((sum, value) => sum + value, 0) / means.length : null, students: classStudents };
    });
    const means = reportStudents.map(student => student.meanPercentage).filter((value): value is number => value !== null);
    const scopeMean = means.length ? means.reduce((sum, value) => sum + value, 0) / means.length : null;
    const title = mode === "form" ? `${form.selectedForm} Results Register` : `${sections[0]?.title ?? "Class"} Results Register`;
    openRosterPdf(classSheet.data.school.name, title, classSheet.data.term.name, scopeMean, sections);
  };
  return <WorkflowCard title="Editable learner report card" copy="Enter marks for one learner, or switch to the whole-class sheet to fill every learner’s subject marks together. Generate a class or whole-form results register and mean as a printable PDF.">
    <div className="grid gap-3 sm:grid-cols-2">
      <div><Label>Report workflow</Label><div className="mt-2"><Select value={mode} onValueChange={value => setMode(value as typeof mode)}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="learner">One learner · editable sheet</SelectItem><SelectItem value="class">Whole class · editable sheet</SelectItem><SelectItem value="form">Whole form · results PDF</SelectItem></SelectContent></Select></div></div>
      {mode === "form" ? <div><Label>Form</Label><div className="mt-2"><Select value={form.selectedForm} onValueChange={value => setForm(current => ({ ...current, selectedForm: value as typeof current.selectedForm }))}><SelectTrigger className="rounded-xl"><SelectValue /></SelectTrigger><SelectContent>{["Form 1", "Form 2", "Form 3", "Form 4"].map(value => <SelectItem key={value} value={value}>{value}</SelectItem>)}</SelectContent></Select></div></div> : <div><Label>Class</Label><div className="mt-2"><ClassSelect classes={classes} value={form.classId} onChange={value => setForm(current => ({ ...current, classId: value, studentId: "" }))} /></div></div>}
      {mode === "learner" ? <div><Label>Learner</Label><div className="mt-2"><StudentSelect students={students.data ?? []} value={form.studentId} onChange={value => setForm(current => ({ ...current, studentId: value }))} /></div></div> : null}
      <div><Label>Academic year</Label><div className="mt-2"><YearSelect years={years} value={form.yearId} onChange={value => setForm(current => ({ ...current, yearId: value, termId: "" }))} /></div></div>
      <div><Label>Term</Label><div className="mt-2"><TermSelect terms={terms} yearId={form.yearId} value={form.termId} onChange={value => setForm(current => ({ ...current, termId: value }))} /></div></div>
    </div>
    {mode === "learner" ? (!hasScope || !form.studentId ? <p className="mt-4 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">Select the class, learner, academic year, and term to open the editable subject sheet.</p> : sheet.isLoading ? <p className="mt-4 text-sm text-slate-500">Loading the learner’s assigned subjects…</p> : sheet.error ? <p role="alert" className="mt-4 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700">The editable sheet could not be opened: {sheet.error.message}</p> : sheet.data ? <form onSubmit={saveSheet} className="mt-4 space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl bg-[#f4f7f5] p-3 text-sm dark:bg-white/5"><div><p className="font-semibold">{sheet.data.student.firstName} {sheet.data.student.lastName}</p><p className="text-xs text-slate-500">{sheet.data.student.admissionNo} · {sheet.data.classRecord.form} {sheet.data.classRecord.stream} · {sheet.data.term.name}</p></div><Badge className={cn("border-0", sheet.data.existingReportCardId ? "bg-[#fbf1d8] text-[#94651f]" : "bg-[#e8f1ec] text-[#0d4437]")}>{sheet.data.wasPublished ? "Published — save returns it to draft" : sheet.data.existingReportCardId ? "Existing draft · editable" : "New draft"}</Badge></div>
      <div className="overflow-x-auto rounded-xl border border-emerald-950/8 dark:border-white/8"><table className="w-full min-w-[700px] text-left text-sm"><thead className="bg-[#f4f7f5] text-xs uppercase tracking-wide text-slate-500 dark:bg-white/5"><tr><th className="px-3 py-3">Subject</th><th className="w-36 px-3 py-3">Mark</th><th className="w-36 px-3 py-3">Out of</th><th className="w-32 px-3 py-3">Percent</th><th className="px-3 py-3">Subject comment (optional)</th></tr></thead><tbody>{rows.map(row => { const percentage = row.score !== "" && Number(row.maxMarks) > 0 ? `${(Number(row.score) / Number(row.maxMarks) * 100).toFixed(1)}%` : "—"; return <tr key={row.subjectId} className="border-t border-emerald-950/7 dark:border-white/8"><td className="px-3 py-3"><p className="font-semibold">{row.subject}</p><p className="text-xs text-slate-500">{row.subjectCode}</p></td><td className="px-3 py-3"><Input aria-label={`${row.subject} mark`} type="number" inputMode="decimal" min="0" max={row.maxMarks || undefined} step="0.01" placeholder="Enter mark" value={row.score} onChange={event => updateRow(row.subjectId, { score: event.target.value })} className="h-10 min-w-24 rounded-lg" /></td><td className="px-3 py-3"><Input aria-label={`${row.subject} maximum mark`} type="number" inputMode="decimal" min="0.01" step="0.01" value={row.maxMarks} onChange={event => updateRow(row.subjectId, { maxMarks: event.target.value })} className="h-10 min-w-24 rounded-lg" /></td><td className="px-3 py-3 font-medium tabular-nums">{percentage}</td><td className="px-3 py-3"><Input aria-label={`${row.subject} comment`} maxLength={500} placeholder="Optional note" value={row.comment} onChange={event => updateRow(row.subjectId, { comment: event.target.value })} className="h-10 min-w-40 rounded-lg" /></td></tr>; })}</tbody></table></div>
      <div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#f4f7f5] p-3 dark:bg-white/5"><p className="text-xs text-slate-500">Subjects</p><p className="text-xl font-semibold">{rows.length}</p></div><div className="rounded-xl bg-[#f4f7f5] p-3 dark:bg-white/5"><p className="text-xs text-slate-500">Marks entered</p><p className="text-xl font-semibold">{filledCount} / {rows.length}</p></div><div className="rounded-xl bg-[#f4f7f5] p-3 dark:bg-white/5"><p className="text-xs text-slate-500">Current average</p><p className="text-xl font-semibold">{average.toFixed(1)}%</p></div></div>
      <div><Label htmlFor="editable-report-comment">Class teacher comment (optional)</Label><Textarea id="editable-report-comment" value={teacherComment} onChange={event => setTeacherComment(event.target.value)} placeholder="Add a comment for this learner" className="mt-2 min-h-24 rounded-xl" maxLength={1200} /></div>
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-emerald-950/8 p-3 dark:border-white/8"><p className="text-xs leading-5 text-slate-500">Saving creates or updates a draft report card. Every listed subject needs a valid mark; learners see it only after the class/term drafts are published.</p><Button type="submit" className="rounded-xl bg-[#0d4437] text-white hover:bg-[#092f26]" disabled={!complete || save.isPending}>{save.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <FileText className="mr-2 h-4 w-4" />}{sheet.data.existingReportCardId ? "Save report-card changes" : "Save marks & report-card draft"}</Button></div>
    </form> : null) : !classSheetEnabled ? <p className="mt-4 rounded-xl border border-dashed border-emerald-950/12 p-4 text-sm text-slate-500 dark:border-white/12 dark:text-slate-400">Choose a {mode === "class" ? "class" : "form"}, academic year, and term to open the results register.</p> : classSheet.isLoading ? <p className="mt-4 text-sm text-slate-500">Loading all learners and term results…</p> : classSheet.error ? <p role="alert" className="mt-4 rounded-xl border border-rose-200 bg-rose-50 p-4 text-sm text-rose-700">The results register could not be opened: {classSheet.error.message}</p> : classSheet.data ? <div className="mt-4 space-y-4">
      <div className="grid gap-3 sm:grid-cols-3"><div className="rounded-xl bg-[#e8f1ec] p-3 dark:bg-emerald-950/30"><p className="text-xs text-slate-500">{mode === "form" ? `${form.selectedForm} mean` : "Whole-class mean"}</p><p className="text-2xl font-bold text-[#0d4437] dark:text-emerald-300">{(mode === "class" ? liveClassMean : classSheet.data.scopeMean) === null ? "—" : `${(mode === "class" ? liveClassMean : classSheet.data.scopeMean)?.toFixed(2)}%`}</p><p className="text-xs text-slate-500">Learner-balanced average of each learner’s subject percentages</p></div><div className="rounded-xl bg-[#f4f7f5] p-3 dark:bg-white/5"><p className="text-xs text-slate-500">Learners in register</p><p className="text-2xl font-bold">{roster.length}</p><p className="text-xs text-slate-500">Listed alphabetically within each class</p></div><div className="rounded-xl bg-[#fbf1d8] p-3 dark:bg-amber-950/30"><p className="text-xs text-slate-500">Entered subject marks</p><p className="text-2xl font-bold">{mode === "class" ? `${bulkFilled} / ${bulkRequired.length}` : classSheet.data.totalMarkEntries}</p><p className="text-xs text-slate-500">{classSheet.data.term.name} · {classSheet.data.studentsWithMarks} learners with marks</p></div></div>
      {mode === "form" && classSheet.data.classSummaries.length ? <div className="grid gap-2 sm:grid-cols-2 xl:grid-cols-4">{classSheet.data.classSummaries.map(item => <div key={item.classId} className="rounded-xl border border-emerald-950/8 p-3 dark:border-white/8"><p className="font-semibold">{item.form} · {item.stream}</p><p className="mt-1 text-lg font-bold text-[#0d4437] dark:text-emerald-300">{item.averagePercentage === null ? "—" : `${item.averagePercentage.toFixed(2)}%`}</p><p className="text-xs text-slate-500">Mean · {item.studentsWithMarks}/{item.totalStudents} learners with marks</p></div>)}</div> : null}
      {mode === "class" && learnersWithoutSubjects.length ? <p role="alert" className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-800">Assign subjects to {learnersWithoutSubjects.length} learner(s) before saving the whole-class sheet. Their names remain included in the results register.</p> : null}
      {mode === "class" ? <div className="overflow-x-auto rounded-xl border border-emerald-950/8 dark:border-white/8"><table className="w-full min-w-[900px] text-left text-xs"><thead className="bg-[#f4f7f5] text-slate-600 dark:bg-white/5"><tr><th className="sticky left-0 z-10 bg-[#f4f7f5] px-2 py-3 dark:bg-[#172420]"># / learner</th><th className="px-2 py-3">Admission no.</th>{rosterSubjects.map(subject => <th key={subject.id} className="min-w-32 px-2 py-2"><p className="font-semibold">{subject.name}</p><p className="text-[10px] text-slate-500">{subject.code}</p><div className="mt-1 flex items-center gap-1"><span className="normal-case text-[10px]">Out of</span><Input aria-label={`Maximum mark for ${subject.name}`} type="number" min="0.01" step="0.01" value={bulkMaxMarks[subject.id] ?? "100"} onChange={event => setBulkMaxMarks(current => ({ ...current, [subject.id]: event.target.value }))} className="h-7 w-16 rounded-md bg-white px-1 text-xs dark:bg-[#172420]" /></div></th>)}<th className="px-2 py-3">Mean %</th></tr></thead><tbody>{roster.map((learner, index) => <tr key={learner.id} className="border-t border-emerald-950/7 dark:border-white/8"><td className="sticky left-0 bg-white px-2 py-2 dark:bg-[#172420]"><span className="mr-1 text-slate-400">{index + 1}.</span><span className="font-semibold">{learner.lastName}, {learner.firstName}</span></td><td className="px-2 py-2 font-mono">{learner.admissionNo}</td>{rosterSubjects.map(subject => { const learnerSubject = learner.subjects.find(row => row.subjectId === subject.id); const key = `${learner.id}:${subject.id}`; return <td key={subject.id} className="px-2 py-2">{learnerSubject ? <Input aria-label={`${learner.firstName} ${learner.lastName} ${subject.name} mark`} type="number" inputMode="decimal" min="0" max={bulkMaxMarks[subject.id] ?? learnerSubject.maxMarks} step="0.01" placeholder="—" value={bulkMarks[key] ?? ""} onChange={event => setBulkMarks(current => ({ ...current, [key]: event.target.value }))} className="h-9 w-24 rounded-lg" /> : <span className="text-slate-300">Not enrolled</span>}</td>; })}<td className="px-2 py-2 font-semibold tabular-nums">{bulkStudentMeans.get(learner.id) === null ? "—" : `${bulkStudentMeans.get(learner.id)?.toFixed(1)}%`}</td></tr>)}</tbody></table></div> : <div className="overflow-x-auto rounded-xl border border-emerald-950/8 dark:border-white/8"><table className="w-full min-w-[760px] text-left text-xs"><thead className="bg-[#f4f7f5] text-slate-600 dark:bg-white/5"><tr><th className="px-3 py-3">#</th><th className="px-3 py-3">Learner</th><th className="px-3 py-3">Admission no.</th><th className="px-3 py-3">Class</th>{rosterSubjects.map(subject => <th key={subject.id} className="px-3 py-3">{subject.name}</th>)}<th className="px-3 py-3">Mean %</th></tr></thead><tbody>{roster.map((learner, index) => <tr key={learner.id} className="border-t border-emerald-950/7 dark:border-white/8"><td className="px-3 py-2">{index + 1}</td><td className="px-3 py-2 font-semibold">{learner.lastName}, {learner.firstName}</td><td className="px-3 py-2 font-mono">{learner.admissionNo}</td><td className="px-3 py-2">{learner.form} · {learner.stream}</td>{rosterSubjects.map(subject => { const mark = learner.subjects.find(row => row.subjectId === subject.id); return <td key={subject.id} className="px-3 py-2">{mark?.score === null || !mark ? "—" : `${mark.score} / ${mark.maxMarks}`}</td>; })}<td className="px-3 py-2 font-semibold">{learner.meanPercentage === null ? "—" : `${learner.meanPercentage.toFixed(1)}%`}</td></tr>)}</tbody></table></div>}
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-emerald-950/8 p-3 dark:border-white/8"><p className="text-xs leading-5 text-slate-500">{mode === "class" ? "Enter marks across the entire class in one grid. The PDF includes every learner, subject marks, individual mean, class mean, and rank; the whole-form report includes class-by-class means." : "The whole-form PDF lists every active learner in every class, with each class mean and the overall form mean. Learners are ordered by class and alphabetically by surname."}</p><div className="flex gap-2"><Button type="button" variant="outline" className="rounded-xl" onClick={printResults}><FileText className="mr-2 h-4 w-4" />Print / save PDF</Button>{mode === "class" ? <Button type="button" className="rounded-xl bg-[#0d4437] text-white hover:bg-[#092f26]" disabled={!bulkComplete || learnersWithoutSubjects.length > 0 || saveClass.isPending} onClick={saveClassSheet}>{saveClass.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <CheckCircle2 className="mr-2 h-4 w-4" />}Save all {roster.length} report cards</Button> : null}</div></div>
    </div> : null}
  </WorkflowCard>;
}
